def to_label(f):
    """
        convert a float to a label that makes sense
    """
    if f < 0.1:
        return "%.3f" % f
    elif f < 1.0:
        return "%.2f" % f
    elif f < 10.0:
        return "%.1f" % f
    else:
        return "%d" % int(f)

